var path=form.querySelector('[name="background_path"]'),greeting=form.querySelector('[name="greeting"]'),bg=form.querySelector('[name="bg_color"]'),fg=form.querySelector('[name="text_color"]');
var preview=document.getElementById('v11-card-preview'),copy=document.getElementById('v11-card-copy'),state=document.getElementById('v11-upload-state'),file=document.getElementById('v11-bg-upload');
var originalUrl=<?php echo json_encode($editTemplate&&!empty($editTemplate['background_path'])?toimage($editTemplate['background_path']):'',JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
var pictureUrl=originalUrl;
function validHex(s){return /^#[a-f0-9]{6}$/i.test((s||'').trim());}
function update(){var b=bg.value,f=fg.value;preview.style.backgroundColor=validHex(b)?b:'#8b2337';preview.style.color=validHex(f)?f:'#fff4de';preview.style.backgroundImage=pictureUrl?'url("'+pictureUrl.replace(/"/g,'%22')+'")':'none';copy.textContent=(greeting.value||'祝您平安喜乐').slice(0,200);}
[greeting,bg,fg].forEach(function(el){el.addEventListener('input',update)});
document.querySelectorAll('.v11-color-preset').forEach(function(btn){btn.addEventListener('click',function(){bg.value=btn.getAttribute('data-bg');fg.value=btn.getAttribute('data-fg');update();});});
document.getElementById('v11-clear-bg').addEventListener('click',function(){path.value='';pictureUrl='';update();state.textContent='已移除模板背景图片，保存模板后生效；原附件文件不会删除。';});
document.getElementById('v11-manual-apply').addEventListener('click',function(){var val=document.getElementById('v11-bg-manual').value.trim();if(!/^images\/[0-9]+\/[A-Za-z0-9_./-]+\.(png|jpg|jpeg|webp)$/i.test(val)||val.indexOf('..')!==-1){state.textContent='请使用有效的微擎附件相对路径';return;}path.value=val;pictureUrl='';update();state.textContent='已填写附件路径，请保存后检查小程序真实显示';});
file.addEventListener('change',function(){if(!file.files||!file.files[0])return;var f=file.files[0];if(f.size>8*1024*1024){state.textContent='文件不能超过8MB';file.value='';return;}var data=new FormData();data.append('v11_upload_background','1');data.append('token',form.querySelector('[name="token"]').value);data.append('v11_background_file',f);var button=document.querySelector('.v11-uploader');button.style.pointerEvents='none';state.textContent='正在上传并优化图片…';var xhr=new XMLHttpRequest();xhr.open('POST',<?php echo json_encode($this->createWebUrl('v11',array('pane'=>'templates')),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,true);xhr.timeout=60000;xhr.onreadystatechange=function(){if(xhr.readyState!==4)return;button.style.pointerEvents='';file.value='';var r;try{r=JSON.parse(xhr.responseText);}catch(e){state.textContent='服务端没有返回有效结果，请检查PHP日志和请求大小限制';return;}if(xhr.status!==200||!r.ok){state.textContent=(r&&r.message)||'上传失败';return;}path.value=r.path;pictureUrl=r.url;state.textContent='✓ 已上传并优化为 '+r.width+'×'+r.height+'（'+Math.max(1,Math.round(r.bytes/1024))+'KB），请点击“保存模板”生效';update();};xhr.onerror=function(){button.style.pointerEvents='';state.textContent='网络异常，图片上传失败';};xhr.ontimeout=function(){button.style.pointerEvents='';state.textContent='上传超时，请重试';};xhr.send(data);});
var voice=document.getElementById('v11-audio-file'),audioPath=document.getElementById('v11-audio-path'),player=document.getElementById('v11-audio-preview'),audioState=document.getElementById('v11-audio-state');
var currentAudio=<?php echo json_encode($editTemplate&&!empty($editTemplate['audio_path'])?toimage($editTemplate['audio_path']):'',JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
if(currentAudio){player.src=currentAudio;player.style.display='block';}
document.getElementById('v11-audio-clear').addEventListener('click',function(){audioPath.value='';player.pause();player.removeAttribute('src');player.style.display='none';audioState.textContent='已移除语音，保存模板后生效；原文件不会删除';});
voice.addEventListener('change',function(){if(!voice.files||!voice.files[0])return;var f=voice.files[0];if(f.size>5*1024*1024){audioState.textContent='文件超过5MB';voice.value='';return;}
 var data=new FormData();data.append('v11_upload_audio','1');data.append('token',form.querySelector('[name="token"]').value);data.append('v11_audio_file',f);
 audioState.textContent='正在上传MP3…';var xhr=new XMLHttpRequest();xhr.open('POST',<?php echo json_encode($this->createWebUrl('v11',array('pane'=>'templates')),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,true);xhr.timeout=60000;
 xhr.onreadystatechange=function(){if(xhr.readyState!==4)return;voice.value='';var r;try{r=JSON.parse(xhr.responseText);}catch(e){audioState.textContent='服务器返回异常，请检查音频大小及PHP日志';return;}if(xhr.status!==200||!r.ok){audioState.textContent=(r&&r.message)||'上传失败';return;}
 audioPath.value=r.path;player.src=r.url;player.style.display='block';audioState.textContent='✓ MP3已上传（'+Math.max(1,Math.round(r.bytes/1024))+'KB），保存模板后生效';};xhr.onerror=function(){audioState.textContent='网络错误，请重试';};xhr.ontimeout=function(){audioState.textContent='上传超时，请重试';};xhr.send(data);
});
update();
})();
</script>
<?php endif; ?>
